import json
import unittest

import dataclasses, importlib
MOD = "campaign.sheets"

def run_case(case):
    mod = importlib.import_module(MOD)
    c = case["sheet"]
    sheet = mod.Sheet(name=c["name"], hp=c["hp"], max_hp=c["max_hp"], ac=c["ac"], conditions=list(c["conditions"]),
                      inventory=[mod.Item(name=i["name"], weight=i["weight"], count=i.get("count", 1)) for i in c["inventory"]])
    results = []
    for op in case["ops"]:
        try:
            if op[0] == "add_item":
                i = op[1]
                res = mod.add_item(sheet, mod.Item(name=i["name"], weight=i["weight"], count=i.get("count", 1)))
            else:
                res = getattr(mod, op[0])(sheet, *op[1:]) if op[0] in ("take_damage", "heal") else getattr(mod, op[0])(sheet)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return {"results": results, "sheet": dataclasses.asdict(sheet)}

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"sheet\": {\"name\": \"Yoru\", \"hp\": 14, \"max_hp\": 22, \"ac\": 13, \"inventory\": [], \"conditions\": [\"dead\", \"prone\"]}, \"ops\": [[\"heal\", 0], [\"add_item\", {\"name\": \"lantern\", \"weight\": 3}], [\"take_damage\", -1], [\"add_item\", {\"name\": \"potion\", \"weight\": 1, \"count\": 3}], [\"heal\", -2], [\"take_damage\", 0], [\"add_item\", {\"name\": \"rope\", \"weight\": 5}], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"raises\": \"ValueError\"}, 1, {\"raises\": \"ValueError\"}, 3, {\"raises\": \"ValueError\"}, 14, 1, \"Yoru 14/22 AC13 [dead,prone]\", 11], \"sheet\": {\"name\": \"Yoru\", \"hp\": 14, \"max_hp\": 22, \"ac\": 13, \"conditions\": [\"dead\", \"prone\"], \"inventory\": [{\"name\": \"lantern\", \"weight\": 3, \"count\": 1}, {\"name\": \"potion\", \"weight\": 1, \"count\": 3}, {\"name\": \"rope\", \"weight\": 5, \"count\": 1}]}}"))

    def test_example_2(self):
        case = json.loads("{\"sheet\": {\"name\": \"Brix\", \"hp\": 28, \"max_hp\": 33, \"ac\": 14, \"inventory\": [{\"name\": \"potion\", \"weight\": 1}, {\"name\": \"shield\", \"weight\": 12}], \"conditions\": []}, \"ops\": [[\"add_item\", {\"name\": \"rations\", \"weight\": 1, \"count\": 2}], [\"heal\", -2], [\"heal\", 20], [\"take_damage\", 12], [\"heal\", 20], [\"heal\", 0], [\"heal\", 0], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [2, {\"raises\": \"ValueError\"}, 33, 21, 33, 33, 33, \"Brix 33/33 AC14 [ok]\", 15], \"sheet\": {\"name\": \"Brix\", \"hp\": 33, \"max_hp\": 33, \"ac\": 14, \"conditions\": [], \"inventory\": [{\"name\": \"potion\", \"weight\": 1, \"count\": 1}, {\"name\": \"shield\", \"weight\": 12, \"count\": 1}, {\"name\": \"rations\", \"weight\": 1, \"count\": 2}]}}"))

    def test_example_3(self):
        case = json.loads("{\"sheet\": {\"name\": \"Yoru\", \"hp\": 4, \"max_hp\": 19, \"ac\": 10, \"inventory\": [], \"conditions\": [\"poisoned\"]}, \"ops\": [[\"heal\", -2], [\"add_item\", {\"name\": \"rope\", \"weight\": 5, \"count\": 1}], [\"take_damage\", -1], [\"take_damage\", -1], [\"heal\", -2], [\"take_damage\", -1], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"raises\": \"ValueError\"}, 1, {\"raises\": \"ValueError\"}, {\"raises\": \"ValueError\"}, {\"raises\": \"ValueError\"}, {\"raises\": \"ValueError\"}, \"Yoru 4/19 AC10 [poisoned]\", 5], \"sheet\": {\"name\": \"Yoru\", \"hp\": 4, \"max_hp\": 19, \"ac\": 10, \"conditions\": [\"poisoned\"], \"inventory\": [{\"name\": \"rope\", \"weight\": 5, \"count\": 1}]}}"))


