        self.assertEqual(norm(run_case(case)), json.loads("{\"scaled\": [{\"name\": \"egg\", \"qty\": 0, \"unit\": \"g\", \"optional\": false}, {\"name\": \"butter\", \"qty\": 1.5, \"unit\": \"l\", \"optional\": true}, {\"name\": \"sesame\", \"qty\": 1.5, \"unit\": \"l\", \"optional\": false}, {\"name\": \"oat\", \"qty\": 126, \"unit\": \"pcs\", \"optional\": true}], \"shopping\": [[\"egg\", 2, \"g\"], [\"sesame\", 3, \"l\"]], \"allergens\": [\"egg\", \"gluten\", \"nuts\"], \"rendered\": [\"egg: 2 g\", \"butter: 3 l (optional)\", \"sesame: 3 l\", \"oat: 250.5 pcs (optional)\"]}"))

