import json
import unittest

import dataclasses, importlib
MOD = "intake.samples"

def run_case(case):
    mod = importlib.import_module(MOD)
    samples = [mod.Sample(*s) for s in case["samples"]]
    d = dataclasses.asdict
    out = {"stale": [mod.is_stale(s, case["today"]) for s in samples], "labels": [mod.label(s) for s in samples],
           "warm": mod.warm(samples, case["limit"]), "total": mod.total_volume(samples, case["kind"]),
           "chilled": [d(mod.chill(s, case["to_temp"])) for s in samples]}
    try:
        out["aliquots"] = [d(a) for a in mod.aliquot(samples[0], case["parts"])]
    except ValueError as e:
        out["aliquots"] = {"raises": "ValueError"}
    return out

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"samples\": [[\"S00\", \"tissue\", 95, 21.0, 10.0], [\"S01\", \"serum\", 91, 8.5, 4.3], [\"S02\", \"urine\", 95, 37.0, 10.0], [\"S03\", \"urine\", 88, -20.0, 1.0], [\"S04\", \"serum\", 89, 21.0, 4.3]], \"today\": 101, \"parts\": 4, \"limit\": 30.0, \"to_temp\": 4.0, \"kind\": null}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"stale\": [true, true, true, true, true], \"labels\": [\"S00/TIS/95\", \"S01/SER/91\", \"S02/URI/95\", \"S03/URI/88\", \"S04/SER/89\"], \"warm\": [\"S02\"], \"total\": 29.6, \"chilled\": [{\"sample_id\": \"S00\", \"kind\": \"tissue\", \"received_day\": 95, \"temp_c\": 4.0, \"volume_ml\": 10.0}, {\"sample_id\": \"S01\", \"kind\": \"serum\", \"received_day\": 91, \"temp_c\": 4.0, \"volume_ml\": 4.3}, {\"sample_id\": \"S02\", \"kind\": \"urine\", \"received_day\": 95, \"temp_c\": 4.0, \"volume_ml\": 10.0}, {\"sample_id\": \"S03\", \"kind\": \"urine\", \"received_day\": 88, \"temp_c\": -20.0, \"volume_ml\": 1.0}, {\"sample_id\": \"S04\", \"kind\": \"serum\", \"received_day\": 89, \"temp_c\": 4.0, \"volume_ml\": 4.3}], \"aliquots\": [{\"sample_id\": \"S00-a\", \"kind\": \"tissue\", \"received_day\": 95, \"temp_c\": 21.0, \"volume_ml\": 2.5}, {\"sample_id\": \"S00-b\", \"kind\": \"tissue\", \"received_day\": 95, \"temp_c\": 21.0, \"volume_ml\": 2.5}, {\"sample_id\": \"S00-c\", \"kind\": \"tissue\", \"received_day\": 95, \"temp_c\": 21.0, \"volume_ml\": 2.5}, {\"sample_id\": \"S00-d\", \"kind\": \"tissue\", \"received_day\": 95, \"temp_c\": 21.0, \"volume_ml\": 2.5}]}"))

    def test_example_2(self):
        case = json.loads("{\"samples\": [[\"S00\", \"tissue\", 85, 37.0, 4.3], [\"S01\", \"urine\", 96, 37.0, 1.0], [\"S02\", \"urine\", 88, 4.0, 0.5], [\"S03\", \"urine\", 98, 8.5, 2.5], [\"S04\", \"swab\", 94, -20.0, 10.0]], \"today\": 96, \"parts\": 0, \"limit\": 4.0, \"to_temp\": -80.0, \"kind\": null}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"stale\": [true, false, true, false, false], \"labels\": [\"S00/TIS/85\", \"S01/URI/96\", \"S02/URI/88\", \"S03/URI/98\", \"S04/SWA/94\"], \"warm\": [\"S00\", \"S01\", \"S03\"], \"total\": 18.3, \"chilled\": [{\"sample_id\": \"S00\", \"kind\": \"tissue\", \"received_day\": 85, \"temp_c\": -80.0, \"volume_ml\": 4.3}, {\"sample_id\": \"S01\", \"kind\": \"urine\", \"received_day\": 96, \"temp_c\": -80.0, \"volume_ml\": 1.0}, {\"sample_id\": \"S02\", \"kind\": \"urine\", \"received_day\": 88, \"temp_c\": -80.0, \"volume_ml\": 0.5}, {\"sample_id\": \"S03\", \"kind\": \"urine\", \"received_day\": 98, \"temp_c\": -80.0, \"volume_ml\": 2.5}, {\"sample_id\": \"S04\", \"kind\": \"swab\", \"received_day\": 94, \"temp_c\": -80.0, \"volume_ml\": 10.0}], \"aliquots\": {\"raises\": \"ValueError\"}}"))

    def test_example_3(self):
        case = json.loads("{\"samples\": [[\"S00\", \"urine\", 80, 21.0, 2.5], [\"S01\", \"serum\", 87, 4.0, 4.3], [\"S02\", \"urine\", 84, -20.0, 1.0]], \"today\": 96, \"parts\": 1, \"limit\": 10.0, \"to_temp\": -80.0, \"kind\": null}")
