import json
import unittest

import dataclasses, importlib
MOD = "campaign.sheets"

def run_case(case):
    mod = importlib.import_module(MOD)
    c = case["sheet"]
    sheet = mod.Sheet(name=c["name"], hp=c["hp"], max_hp=c["max_hp"], ac=c["ac"], conditions=list(c["conditions"]),
                      inventory=[mod.Item(name=i["name"], weight=i["weight"], count=i.get("count", 1)) for i in c["inventory"]])
    results = []
    for op in case["ops"]:
        try:
            if op[0] == "add_item":
                i = op[1]
                res = mod.add_item(sheet, mod.Item(name=i["name"], weight=i["weight"], count=i.get("count", 1)))
            else:
                res = getattr(mod, op[0])(sheet, *op[1:]) if op[0] in ("take_damage", "heal") else getattr(mod, op[0])(sheet)
        except Exception as e:
            res = {"raises": type(e).__name__}
        results.append(res)
    return {"results": results, "sheet": dataclasses.asdict(sheet)}

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"sheet\": {\"name\": \"Brix\", \"hp\": 7, \"max_hp\": 17, \"ac\": 13, \"inventory\": [{\"name\": \"lantern\", \"weight\": 3, \"count\": 1}, {\"name\": \"rope\", \"weight\": 5}], \"conditions\": []}, \"ops\": [[\"heal\", -2], [\"add_item\", {\"name\": \"rope\", \"weight\": 5, \"count\": 1}], [\"add_item\", {\"name\": \"lantern\", \"weight\": 3}], [\"carried_weight\"], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"raises\": \"ValueError\"}, 2, 2, 16, \"Brix 7/17 AC13 [ok]\", 16], \"sheet\": {\"name\": \"Brix\", \"hp\": 7, \"max_hp\": 17, \"ac\": 13, \"conditions\": [], \"inventory\": [{\"name\": \"lantern\", \"weight\": 3, \"count\": 2}, {\"name\": \"rope\", \"weight\": 5, \"count\": 2}]}}"))

    def test_example_2(self):
        case = json.loads("{\"sheet\": {\"name\": \"Pell\", \"hp\": 22, \"max_hp\": 35, \"ac\": 9, \"inventory\": [{\"name\": \"rope\", \"weight\": 5}], \"conditions\": []}, \"ops\": [[\"add_item\", {\"name\": \"shield\", \"weight\": 12, \"count\": 4}], [\"add_item\", {\"name\": \"shield\", \"weight\": 12}], [\"add_item\", {\"name\": \"shield\", \"weight\": 12}], [\"add_item\", {\"name\": \"potion\", \"weight\": 1}], [\"take_damage\", 50], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"raises\": \"ValueError\"}, 1, 2, 1, 0, \"Pell 0/35 AC9 [down]\", 30], \"sheet\": {\"name\": \"Pell\", \"hp\": 0, \"max_hp\": 35, \"ac\": 9, \"conditions\": [\"down\"], \"inventory\": [{\"name\": \"rope\", \"weight\": 5, \"count\": 1}, {\"name\": \"shield\", \"weight\": 12, \"count\": 2}, {\"name\": \"potion\", \"weight\": 1, \"count\": 1}]}}"))

    def test_example_3(self):
        case = json.loads("{\"sheet\": {\"name\": \"Pell\", \"hp\": 24, \"max_hp\": 34, \"ac\": 14, \"inventory\": [{\"name\": \"lantern\", \"weight\": 3, \"count\": 3}, {\"name\": \"potion\", \"weight\": 1}], \"conditions\": [\"dead\"]}, \"ops\": [[\"add_item\", {\"name\": \"rope\", \"weight\": 5}], [\"take_damage\", 0], [\"take_damage\", 50], [\"take_damage\", -1], [\"add_item\", {\"name\": \"shield\", \"weight\": 12}], [\"heal\", 20], [\"status_line\"], [\"carried_weight\"]]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [1, 24, 0, {\"raises\": \"ValueError\"}, 1, {\"raises\": \"ValueError\"}, \"Pell 0/34 AC14 [dead,down]\", 27], \"sheet\": {\"name\": \"Pell\", \"hp\": 0, \"max_hp\": 34, \"ac\": 14, \"conditions\": [\"dead\", \"down\"], \"inventory\": [{\"name\": \"lantern\", \"weight\": 3, \"count\": 3}, {\"name\": \"potion\", \"weight\": 1, \"count\": 1}, {\"name\": \"rope\", \"weight\": 5, \"count\": 1}, {\"name\": \"shield\", \"weight\": 12, \"count\": 1}]}}"))


