    def test_example_2(self):
        case = json.loads("{\"samples\": [[\"S00\", \"swab\", 93, 8.5, 2.5], [\"S01\", \"tissue\", 82, 21.0, 4.3], [\"S02\", \"swab\", 89, 4.0, 1.0], [\"S03\", \"plasma\", 92, 4.0, 0.5]], \"today\": 101, \"parts\": 4, \"limit\": 30.0, \"to_temp\": 4.0, \"kind\": null}")
