import json
import unittest

import importlib
MOD = "marina.berths"

def run_case(case):
    mod = importlib.import_module(MOD)
    berths = [mod.Berth(id=x["id"], max_len_m=x["max_len_m"], depth_m=x["depth_m"], free=x["free"]) for x in case["berths"]]
    results = []
    for b in case["bookings"]:
        booking = mod.Booking(vessel=b["vessel"], kind=b["kind"], length_m=b["length_m"], draft_m=b["draft_m"], hours=b["hours"], shore_power=b.get("shore_power", False))
        row = {}
        for name, fn in (("fee", lambda: mod.berth_fee(booking)), ("berth", lambda: mod.assign_berth(booking, berths)), ("text", lambda: mod.describe(booking))):
            try:
                row[name] = fn()
            except Exception as e:
                row[name] = {"raises": type(e).__name__}
        results.append(row)
    return {"results": results, "free": mod.free_berths(berths), "berths": [[x.id, x.free] for x in berths]}

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 6.0, \"depth_m\": 4.5, \"free\": true}, {\"id\": \"B1\", \"max_len_m\": 8.5, \"depth_m\": 1.5, \"free\": true}, {\"id\": \"B2\", \"max_len_m\": 10.0, \"depth_m\": 1.5, \"free\": true}, {\"id\": \"B3\", \"max_len_m\": 16.0, \"depth_m\": 2.2, \"free\": true}, {\"id\": \"B4\", \"max_len_m\": 8.5, \"depth_m\": 3.0, \"free\": false}], \"bookings\": [{\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 9.5, \"draft_m\": 2.5, \"hours\": 6}, {\"vessel\": \"Wren\", \"kind\": \"barge\", \"length_m\": 15.0, \"draft_m\": 0.6, \"hours\": 0}, {\"vessel\": \"Skua\", \"kind\": \"sloop\", \"length_m\": 11.0, \"draft_m\": 2.5, \"hours\": 2, \"shore_power\": true}, {\"vessel\": \"Petrel\", \"kind\": \"sloop\", \"length_m\": 5.5, \"draft_m\": 1.0, \"hours\": 6}, {\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 7.0, \"draft_m\": 0.6, \"hours\": 0}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 2760, \"berth\": null, \"text\": \"Merlin (catamaran, 9.5m x 2.5m, 6h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": \"B3\", \"text\": \"Wren (barge, 15.0m x 0.6m, 0h)\"}, {\"fee\": 900, \"berth\": null, \"text\": \"Skua (sloop, 11.0m x 2.5m, 2h +power)\"}, {\"fee\": 2220, \"berth\": \"B0\", \"text\": \"Petrel (sloop, 5.5m x 1.0m, 6h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": \"B1\", \"text\": \"Merlin (catamaran, 7.0m x 0.6m, 0h)\"}], \"free\": [\"B2\"], \"berths\": [[\"B0\", false], [\"B1\", false], [\"B2\", true], [\"B3\", false], [\"B4\", false]]}"))

    def test_example_2(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 8.5, \"depth_m\": 2.2, \"free\": false}, {\"id\": \"B1\", \"max_len_m\": 12.5, \"depth_m\": 4.5, \"free\": true}, {\"id\": \"B2\", \"max_len_m\": 16.0, \"depth_m\": 3.0, \"free\": true}, {\"id\": \"B3\", \"max_len_m\": 8.5, \"depth_m\": 3.0, \"free\": true}, {\"id\": \"B4\", \"max_len_m\": 8.5, \"depth_m\": 2.2, \"free\": true}], \"bookings\": [{\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 15.0, \"draft_m\": 1.0, \"hours\": 2}, {\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 15.0, \"draft_m\": 0.6, \"hours\": 24, \"shore_power\": true}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 920, \"berth\": \"B2\", \"text\": \"Merlin (catamaran, 15.0m x 1.0m, 2h)\"}, {\"fee\": 12960, \"berth\": null, \"text\": \"Merlin (catamaran, 15.0m x 0.6m, 24h +power)\"}], \"free\": [\"B1\", \"B3\", \"B4\"], \"berths\": [[\"B0\", false], [\"B1\", true], [\"B2\", false], [\"B3\", true], [\"B4\", true]]}"))

    def test_example_3(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 10.0, \"depth_m\": 1.5, \"free\": true}, {\"id\": \"B1\", \"max_len_m\": 8.5, \"depth_m\": 2.2, \"free\": true}, {\"id\": \"B2\", \"max_len_m\": 8.5, \"depth_m\": 1.5, \"free\": false}], \"bookings\": [{\"vessel\": \"Merlin\", \"kind\": \"sloop\", \"length_m\": 7.0, \"draft_m\": 1.0, \"hours\": 2, \"shore_power\": true}, {\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 15.0, \"draft_m\": 1.0, \"hours\": 72}, {\"vessel\": \"Merlin\", \"kind\": \"catamaran\", \"length_m\": 7.0, \"draft_m\": 1.0, \"hours\": 0}, {\"vessel\": \"Petrel\", \"kind\": \"barge\", \"length_m\": 15.0, \"draft_m\": 2.5, \"hours\": 0}, {\"vessel\": \"Petrel\", \"kind\": \"barge\", \"length_m\": 15.0, \"draft_m\": 1.0, \"hours\": 24}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 900, \"berth\": \"B1\", \"text\": \"Merlin (sloop, 7.0m x 1.0m, 2h +power)\"}, {\"fee\": 33120, \"berth\": null, \"text\": \"Merlin (catamaran, 15.0m x 1.0m, 72h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": \"B0\", \"text\": \"Merlin (catamaran, 7.0m x 1.0m, 0h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": null, \"text\": \"Petrel (barge, 15.0m x 2.5m, 0h)\"}, {\"fee\": 15600, \"berth\": null, \"text\": \"Petrel (barge, 15.0m x 1.0m, 24h)\"}], \"free\": [], \"berths\": [[\"B0\", false], [\"B1\", false], [\"B2\", false]]}"))


