import json
import unittest

import dataclasses, importlib
MOD = "intake.samples"

def run_case(case):
    mod = importlib.import_module(MOD)
    samples = [mod.Sample(*s) for s in case["samples"]]
    d = dataclasses.asdict
    out = {"stale": [mod.is_stale(s, case["today"]) for s in samples], "labels": [mod.label(s) for s in samples],
           "warm": mod.warm(samples, case["limit"]), "total": mod.total_volume(samples, case["kind"]),
           "chilled": [d(mod.chill(s, case["to_temp"])) for s in samples]}
    try:
        out["aliquots"] = [d(a) for a in mod.aliquot(samples[0], case["parts"])]
    except ValueError as e:
        out["aliquots"] = {"raises": "ValueError"}
    return out

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"samples\": [[\"S00\", \"serum\", 88, 8.5, 2.5], [\"S01\", \"urine\", 97, 4.0, 4.3], [\"S02\", \"swab\", 99, 37.0, 10.0]], \"today\": 107, \"parts\": 1, \"limit\": 30.0, \"to_temp\": 4.0, \"kind\": \"urine\"}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"stale\": [true, true, true], \"labels\": [\"S00/SER/88\", \"S01/URI/97\", \"S02/SWA/99\"], \"warm\": [\"S02\"], \"total\": 4.3, \"chilled\": [{\"sample_id\": \"S00\", \"kind\": \"serum\", \"received_day\": 88, \"temp_c\": 4.0, \"volume_ml\": 2.5}, {\"sample_id\": \"S01\", \"kind\": \"urine\", \"received_day\": 97, \"temp_c\": 4.0, \"volume_ml\": 4.3}, {\"sample_id\": \"S02\", \"kind\": \"swab\", \"received_day\": 99, \"temp_c\": 4.0, \"volume_ml\": 10.0}], \"aliquots\": [{\"sample_id\": \"S00-a\", \"kind\": \"serum\", \"received_day\": 88, \"temp_c\": 8.5, \"volume_ml\": 2.5}]}"))

