import json
import unittest

import dataclasses, importlib
MOD = "canteen.recipes"

def run_case(case):
    mod = importlib.import_module(MOD)
    ings = [mod.Ingredient(*i) for i in case["ingredients"]]
    try:
        scaled = [dataclasses.asdict(x) for x in mod.scale(ings, case["factor"])]
    except ValueError:
        scaled = {"raises": "ValueError"}
    return {"scaled": scaled, "shopping": [list(x) for x in mod.shopping_list(ings, case["pantry"], case["optional"])],
            "allergens": mod.allergens_in(ings), "rendered": mod.render(ings)}

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"ingredients\": [[\"oat\", 0.75, \"pcs\", true], [\"peanut\", 250.5, \"l\", false], [\"rye\", 2, \"pcs\", false], [\"milk\", 2, \"pcs\", false]], \"factor\": 0.5, \"pantry\": {\"flour\": 100, \"butter\": 100, \"egg\": 1, \"milk\": 400}, \"optional\": false}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"scaled\": [{\"name\": \"oat\", \"qty\": 1, \"unit\": \"pcs\", \"optional\": true}, {\"name\": \"peanut\", \"qty\": 125.25, \"unit\": \"l\", \"optional\": false}, {\"name\": \"rye\", \"qty\": 1, \"unit\": \"pcs\", \"optional\": false}, {\"name\": \"milk\", \"qty\": 1, \"unit\": \"pcs\", \"optional\": false}], \"shopping\": [[\"peanut\", 250.5, \"l\"], [\"rye\", 2, \"pcs\"]], \"allergens\": [\"egg\", \"gluten\", \"sesame\"], \"rendered\": [\"oat: 0.75 pcs (optional)\", \"peanut: 250.5 l\", \"rye: 2 pcs\", \"milk: 2 pcs\"]}"))

    def test_example_2(self):
        case = json.loads("{\"ingredients\": [[\"milk\", 250.5, \"g\", true], [\"flour\", 250.5, \"g\", false]], \"factor\": 0, \"pantry\": {\"flour\": 0, \"butter\": 100, \"egg\": 0, \"milk\": 0}, \"optional\": true}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"scaled\": {\"raises\": \"ValueError\"}, \"shopping\": [[\"flour\", 250.5, \"g\"], [\"milk\", 250.5, \"g\"]], \"allergens\": [\"dairy\", \"egg\", \"gluten\", \"sesame\"], \"rendered\": [\"milk: 250.5 g (optional)\", \"flour: 250.5 g\"]}"))

    def test_example_3(self):
        case = json.loads("{\"ingredients\": [[\"butter\", 250.5, \"pcs\", true], [\"rye\", 150, \"l\", false], [\"milk\", 0.75, \"g\", false]], \"factor\": 1.5, \"pantry\": {\"flour\": 0, \"butter\": 100, \"egg\": 400, \"milk\": 1}, \"optional\": false}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"scaled\": [{\"name\": \"butter\", \"qty\": 376, \"unit\": \"pcs\", \"optional\": true}, {\"name\": \"rye\", \"qty\": 225.0, \"unit\": \"l\", \"optional\": false}, {\"name\": \"milk\", \"qty\": 0, \"unit\": \"g\", \"optional\": false}], \"shopping\": [[\"rye\", 150, \"l\"]], \"allergens\": [\"egg\", \"gluten\", \"sesame\"], \"rendered\": [\"butter: 250.5 pcs (optional)\", \"rye: 150 l\", \"milk: 0.75 g\"]}"))


if __name__ == '__main__':
    unittest.main()

