        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 41040, \"berth\": \"B2\", \"text\": \"Wren (sloop, 15.0m x 1.8m, 72h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": null, \"text\": \"Petrel (sloop, 11.0m x 2.5m, 0h)\"}, {\"fee\": 12240, \"berth\": \"B1\", \"text\": \"Merlin (ketch, 9.5m x 1.0m, 72h)\"}, {\"fee\": 4080, \"berth\": null, \"text\": \"Wren (ketch, 9.5m x 0.6m, 24h)\"}, {\"fee\": 2220, \"berth\": null, \"text\": \"Skua (ketch, 15.0m x 1.0m, 6h +power)\"}], \"free\": [\"B0\"], \"berths\": [[\"B0\", true], [\"B1\", false], [\"B2\", false]]}"))

    def test_example_2(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 8.5, \"depth_m\": 3.0, \"free\": true}, {\"id\": \"B1\", \"max_len_m\": 12.5, \"depth_m\": 2.2, \"free\": true}, {\"id\": \"B2\", \"max_len_m\": 8.5, \"depth_m\": 1.5, \"free\": false}], \"bookings\": [{\"vessel\": \"Merlin\", \"kind\": \"sloop\", \"length_m\": 9.5, \"draft_m\": 2.5, \"hours\": 6}, {\"vessel\": \"Wren\", \"kind\": \"barge\", \"length_m\": 7.0, \"draft_m\": 1.0, \"hours\": 24}, {\"vessel\": \"Petrel\", \"kind\": \"barge\", \"length_m\": 7.0, \"draft_m\": 2.5, \"hours\": 2}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 3420, \"berth\": null, \"text\": \"Merlin (sloop, 9.5m x 2.5m, 6h)\"}, {\"fee\": 18000, \"berth\": \"B0\", \"text\": \"Wren (barge, 7.0m x 1.0m, 24h)\"}, {\"fee\": 1500, \"berth\": null, \"text\": \"Petrel (barge, 7.0m x 2.5m, 2h)\"}], \"free\": [\"B1\"], \"berths\": [[\"B0\", false], [\"B1\", true], [\"B2\", false]]}"))

    def test_example_3(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 8.5, \"depth_m\": 4.5, \"free\": true}, {\"id\": \"B1\", \"max_len_m\": 12.5, \"depth_m\": 3.0, \"free\": false}, {\"id\": \"B2\", \"max_len_m\": 10.0, \"depth_m\": 1.5, \"free\": true}, {\"id\": \"B3\", \"max_len_m\": 12.5, \"depth_m\": 1.5, \"free\": true}, {\"id\": \"B4\", \"max_len_m\": 12.5, \"depth_m\": 2.2, \"free\": true}], \"bookings\": [{\"vessel\": \"Petrel\", \"kind\": \"ketch\", \"length_m\": 15.0, \"draft_m\": 1.0, \"hours\": 6}, {\"vessel\": \"Wren\", \"kind\": \"barge\", \"length_m\": 9.5, \"draft_m\": 1.8, \"hours\": 24}, {\"vessel\": \"Merlin\", \"kind\": \"sloop\", \"length_m\": 5.5, \"draft_m\": 1.0, \"hours\": 6, \"shore_power\": true}]}")
