import json
import unittest

import importlib
MOD = "marina.berths"

def run_case(case):
    mod = importlib.import_module(MOD)
    berths = [mod.Berth(id=x["id"], max_len_m=x["max_len_m"], depth_m=x["depth_m"], free=x["free"]) for x in case["berths"]]
    results = []
    for b in case["bookings"]:
        booking = mod.Booking(vessel=b["vessel"], kind=b["kind"], length_m=b["length_m"], draft_m=b["draft_m"], hours=b["hours"], shore_power=b.get("shore_power", False))
        row = {}
        for name, fn in (("fee", lambda: mod.berth_fee(booking)), ("berth", lambda: mod.assign_berth(booking, berths)), ("text", lambda: mod.describe(booking))):
            try:
                row[name] = fn()
            except Exception as e:
                row[name] = {"raises": type(e).__name__}
        results.append(row)
    return {"results": results, "free": mod.free_berths(berths), "berths": [[x.id, x.free] for x in berths]}

def norm(x):
    return json.loads(json.dumps(x))


class RecordTests(unittest.TestCase):
    def test_example_1(self):
        case = json.loads("{\"berths\": [{\"id\": \"B0\", \"max_len_m\": 8.5, \"depth_m\": 4.5, \"free\": true}, {\"id\": \"B1\", \"max_len_m\": 16.0, \"depth_m\": 4.5, \"free\": false}, {\"id\": \"B2\", \"max_len_m\": 6.0, \"depth_m\": 2.2, \"free\": true}, {\"id\": \"B3\", \"max_len_m\": 10.0, \"depth_m\": 3.0, \"free\": true}, {\"id\": \"B4\", \"max_len_m\": 8.5, \"depth_m\": 3.0, \"free\": false}], \"bookings\": [{\"vessel\": \"Petrel\", \"kind\": \"catamaran\", \"length_m\": 9.5, \"draft_m\": 2.5, \"hours\": 72, \"shore_power\": true}, {\"vessel\": \"Wren\", \"kind\": \"barge\", \"length_m\": 7.0, \"draft_m\": 0.6, \"hours\": 6, \"shore_power\": true}, {\"vessel\": \"Merlin\", \"kind\": \"sloop\", \"length_m\": 5.5, \"draft_m\": 1.0, \"hours\": 72}, {\"vessel\": \"Petrel\", \"kind\": \"catamaran\", \"length_m\": 11.0, \"draft_m\": 1.0, \"hours\": 0}]}")
        self.assertEqual(norm(run_case(case)), json.loads("{\"results\": [{\"fee\": 59040, \"berth\": null, \"text\": \"Petrel (catamaran, 9.5m x 2.5m, 72h +power)\"}, {\"fee\": 3420, \"berth\": \"B0\", \"text\": \"Wren (barge, 7.0m x 0.6m, 6h +power)\"}, {\"fee\": 69120, \"berth\": \"B2\", \"text\": \"Merlin (sloop, 5.5m x 1.0m, 72h)\"}, {\"fee\": {\"raises\": \"ValueError\"}, \"berth\": null, \"text\": \"Petrel (catamaran, 11.0m x 1.0m, 0h)\"}], \"free\": [\"B3\"], \"berths\": [[\"B0\", false], [\"B1\", false], [\"B2\", false], [\"B3\", true], [\"B4\", false]]}"))

    def test_example_2(self):
